architecture.h4_f:
msg = CBOR {v: 1, sengwalwa, karabo_go, rometšwe_ka}
ct = AES-GCM-256-Encrypt (k, nonce, msg, aad = kamore_id)
POST / api / likamore / {id} / melaetsa {ciphertext: hex (ct), nonce: hex}

auth.h1_f:
POST /api / netefatšo / ngodisa
  { lebitso la mosebedisi, phasewete, x25519_senotlolo_sa_setšhaba, lebitso_la_pontšo, mohala?, imeile?, avatar_emoji }

Karabo 201 E hlotšwe:
  { phihlello_letshwao, hlabolla_letshwao, mosebedisi_id, lebitso la mosebedisi, ... }

auth.h3_f:
phihlello_token payload: .
  { sub: mosebedisi_id, jti: sesebediswa_id, mofuta: "phihlello", exp: hona joale + 15min }
refresh_token mojaro o moholo: .
  { sub: mosebedisi_id, jti: sesebediswa_id, mofuta: "hlabolla", exp: hona joale + 30d }

HS256-saennwe ka node ya 64-byte sephiri ho tloha .env

auth.h7_f:
POST / api / netefatšo / qr / qala
  → { nonce: 128-bit hex, ttl: 60 } .
QR payload = { nonce, mosebedisi_id, seva: "https://node.mohlala" }

POST / api / netefatšo / qr / netefatša { nonce }
  → sesebediswa se secha ngodisitsoeng; Di-JWT di ile tša boa.

rooms.h6_f:
moromi_bofora = HMAC-SHA256 (kamore_pseudo_letsoai, moromi_id) [: 16] // 32 hex
ciphertext = AES-GCM-Encrypt (kamore_senotlolo, nonce, CBOR_payload, aad = kamore_id)

Fan-tsoa foreime: { mofuta: "m", kamore, msg: {id, ct, nonce, moromi_pseudo, rometsoeng_ka} }

files.h2_f:
init POST / api / difaele / resume / init {lebitso la faele, boholo, chunk_size_hint}
            ← {upload_id, chunk_boholo}
chunk PUT / api / difaele / resume / {upload_id} / chunk / {offset} <ct bytes>
            ← 204. e le
qeta POST / api / difaele / tsosolosa / {upload_id} / qetela {plain_blake3}
            ← 201 {faele_id, url} .
TTL ka e sa fetšwago: 24 h

presence.h1_f:
moreki: ka pele keystroke → romela {mofuta: "t", mmuso:"qala"}
         ga go sa romela bakeng sa 3 s ntle le ge mmušo o fetoga
         10 s ka morago ga go kgotla ga mafelelo ga senotlelo → romela {mohuta:"t", mmušo:"ema"}
seamohedi: auto-emisa 10 s ka mor'a ho qetela "thoma" haeba ha ho "emisa" fihla

calls.h1_f:
POST /api / di-calls / {room_id} / qala {video, mamelwang} → call_id
WS kgašo {mofuta: "c", mofuta:"mema", call_id}
WS kgašo {mofuta: "c", mofuta:" nyehelo", sdp}
WS kgašo {mofuta: "c", mofuta:"karabo", sdp}
WS kgašo {mofuta: "c", mofuta:"nkgetheng", leqhoa} × N
POST / api / dipitso / { call_id} / qetellong

gossip.h3_f:
papatšo = {pubkey, ntlha ya mafelelo, papatšo_ka}
sig = Ed25519-Saena (pubkey_priv, CBOR (papatso))
lesebo payload: [..., {papatso, sig}, ...]

seamogedi: netefatša sig kgahlanong le ad.pubkey → lebenkele iff ok
tlaleletšo: PoW ya 2 ^ 18 e etellang pele mafela ka {pubkey, ntlha ya mafelelo}

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-potšišo {lebitso: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni (senotlolo_sa_setšhaba_go tšwa go_rekoto_ya_HTTPS)
DGA: domain (t) = motheo32 ( SHA256 (peo ∥ YYYY-MM-DD) )[:16] + ".mohlala".

push.h4_f:
iOS NSE: didReceive (kgopelo) { decrypt (kgopelo.diteng.Info ya mosebedisi) }
Android FCM: onMessageReceived (Molaetša wa kgole) { decrypt (Molaetša wa kgole.data) }
Web SW: self.addEventListener ('kgorometsa', e => hlatholla (e.data))

bots.h1_f:
bopa: POST / api / bots {lebitso la mosebedisi, pontšo_lebitso, khoutu}
          → {bot_id, letšoao, senotlolo sa pub}
matha: ka-tshebetso (coroutine ka hare node) .
      OR ya ka ntle (e telele-poll / api / bots / {id} / dimpshafatšo, token-auth'd)
molaetša: {sengwalwa, mosaeno: Ed25519-Saena (bot_priv, canonical_msg)}

security.h4_f:
canary.txt (letsatsi le letsatsi): .
  {letšatšikgwedi, saena: Ed25519-Sign (tokollo_priv, letšatšikgwedi)}
moreki o netefatša → ga e gona goba ga e šome ⇒ kwano e belaelwa

tšhoganetšo: .
  admin POST / api / molaodi / phumola-tšohle {lebaka}
  node dikgašo {mofuta: "n", tiragalo:" kwano", lebaka}
  bareki hlakola dinotlelo, gapeletša gape bootstrap

debugging.h2_f:
sekhahla histograms (ka tsela + mokgwa wa):
  vortex_http_dikgopelo_palomoka {tsela,mokgwa,boemo}
  vortex_http_kgopelo_nako_metsotswana_kgamelo {tsela,mokgwa, le}

dikelo tša websocket: .
  vortex_ws_dikgokagano {node} .
  vortex_ws_fanout_mothaladi_botebo {kamore, mosebedisi}

dibadi tša tlwaelo:
  vortex_melaetša_e rometšwe_palomoka {mohuta_wa_kamore}
  vortex_calls_tholl_palomoka {mofuta}.

