apns.h1_f:
POST https://api.push.apple.com/3/sesebediswa/<sesebediswa_letshwao>
Dihlogo: apns-sehlogo: <bundle_id>, apns-kgorometša-mofuta: temošo, apns-go phuhlama-id: phapoši: 42
Mmele: {aps: {temošo: {thaetlele, mmele}}, ya data: <tiisitswe>}

bmp.h1_f:
id_ya_poso = HKDF (senotlolo_sa_moamohedi, info = "bmp-v1", len = 32)
Peeletšo: POST / bmp / depositi { lebokose la poso_id, blob ≤1MB}
Pickup: GET / bmp / melaetsa (auth'd) .

controller.h1_f:
GET /v1 / botšepehi → {boemo, saennweng_ke, tšoanang, sa tšoanang, ...}
GET / v1 / bophelo bo botle → {boemo, phetolelo, pubkey, dipalopalo}
GET / v1 / dikeno → [{prothokhole, url}, ...]
GET / v1 / liipone → [molaodi_url, ...]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/diprotšeke/<porojeke>/melaetša:romela
Tumelelo: Morwadi <oauth2_token>
Mmele: {molaetsa: {letshwao: <sesebediswa>, ya data: {...tiisitswe ...}, android: {collapse_key}}}

federation.h1_f:
enfelopo = {mohlodi_node, sepheo_mosebedisi, ka hare_ct, ka hare_nonce, rometsoeng_ka}
sig = Ed25519-Sign (mohloli_priv, CBOR (enfelopo))
POST /federation/go tliša {enfelopo, saena}
B netefatsa: saena khahlanong le federations [mohloli_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE melaetsa_fts USING fts5(
  diteng, -- kholomo ya tokenised
  id_ya_kamore UNINDEXED, .
  tokenize = 'unicode61 tlosa_diacritics 2'.
);
potšišo: SELECT rowid FROM melaetsa_fts WHERE dikahare MATCH 'foo'.

gravitix.h1_f:
on /start { emit "O amogetšwe, {ctx.leina_la_pele}" }
ka /oketša <ntho> { .
  state.list = (mmušo.lenaneo goba []) + [ctx.args.item].
  emit "E okeditšwe: {ctx.args.item}".
} .

vapid.h1_f:
VAPID dinotlelo: Ed25519 keypair ka node
letšoao JWT: {aud: kgorometsa_tšebeletso_qalo, exp: hona joale + 12h, sub: mailto: ops@mohlala}
dihlogo tša kgopelo ya kgorometšo: Tumelelo: vapid t = <jwt>, k = <vapid_public_key>
